function flash() { if (!empty($_SESSION['flash'])) { echo '<div class="alert">'.h($_SESSION['flash']).'</div>'; unset($_SESSION['flash']); } }
function simple_pdf($text, $filename='report.pdf') {
    $text = str_replace(["\r","\n"], ['',' '], $text);
    $stream = "BT /F1 12 Tf 50 750 Td (" . addcslashes($text, "()\\") . ") Tj ET";
    $pdf = "%PDF-1.4\n";
    $o1 = "1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj\n";
    $o2 = "2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 >> endobj\n";
    $o3 = "3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >> endobj\n";
    $o4 = "4 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj\n";
    $o5 = "5 0 obj << /Length ".strlen($stream)." >> stream\n$stream\nendstream endobj\n";
    $parts = [$o1,$o2,$o3,$o4,$o5];
    $offsets=[0];
    foreach($parts as $p){$offsets[] = strlen($pdf); $pdf .= $p;}
    $xref = strlen($pdf);
    $pdf .= "xref\n0 6\n0000000000 65535 f \n";
    for($i=1;$i<=5;$i++) $pdf .= sprintf("%010d 00000 n \n", $offsets[$i]);
    $pdf .= "trailer << /Size 6 /Root 1 0 R >>\nstartxref\n$xref\n%%EOF";
    header('Content-Type: application/pdf');
    header('Content-Disposition: attachment; filename='.$filename);
    echo $pdf; exit;
}

