if ($page==='files') { ?><h2>Arquivos</h2><form method="post" action="?page=files_upload" enctype="multipart/form-data" class="panel grid2"><input type="file" name="file" required><select name="client_id"><option value="">Sem cliente</option><?php foreach($clients as $c) echo '<option value="'.$c['id'].'">'.h($c['company_name']).'</option>'; ?></select><select name="project_id"><option value="">Sem projeto</option><?php foreach($projects as $p) echo '<option value="'.$p['id'].'">'.h($p['name']).'</option>'; ?></select><input name="notes" placeholder="Notas"><button>Enviar arquivo</button></form><div class="panel table-wrap"><table><tr><th>Arquivo</th><th>Cliente</th><th>Projeto</th><th>Link</th></tr><?php foreach($files as $f) echo '<tr><td>'.h($f['filename']).'</td><td>'.h($f['company_name']).'</td><td>'.h($f['project_name']).'</td><td><a target="_blank" href="'.h($f['filepath']).'">Abrir</a></td></tr>'; ?></table></div><?php }
if ($page==='approvals') { ?><h2>Aprovações</h2><form method="post" action="?page=approvals_create" class="panel grid2"><select name="client_id"><?php foreach($clients as $c) echo '<option value="'.$c['id'].'">'.h($c['company_name']).'</option>'; ?></select><input name="item_type" placeholder="Tipo item"><input name="item_id" type="number" placeholder="Item ID"><select name="status"><option>draft</option><option>internal review</option><option>sent to client</option><option>approved</option><option>changes requested</option><option>published</option></select><textarea name="notes" placeholder="Notas"></textarea><button>Registrar</button></form><div class="panel table-wrap"><table><tr><th>Cliente</th><th>Item</th><th>Status</th></tr><?php foreach($approvals as $a) echo '<tr><td>'.h($a['company_name']).'</td><td>'.h($a['item_type']).' #'.h($a['item_id']).'</td><td>'.h($a['status']).'</td></tr>'; ?></table></div><?php }
if ($page==='assistant') { ?><h2>Assistente IA</h2><form method="post" action="?page=assistant_ask" class="panel"><textarea name="prompt" placeholder="No que devo focar hoje?" required></textarea><button>Analisar</button></form><div class="panel"><h4>Histórico</h4><ul><?php foreach($ai_logs as $l) echo '<li><b>'.h($l['prompt']).'</b><br>'.h($l['response']).'</li>'; ?></ul></div><?php }
if ($page==='search') {
    $s1=$pdo->prepare('SELECT company_name AS label, "Cliente" AS type FROM clients WHERE company_name LIKE ?');$s1->execute(["%$q%"]);
    $s2=$pdo->prepare('SELECT name AS label, "Projeto" AS type FROM projects WHERE name LIKE ?');$s2->execute(["%$q%"]);
    $s3=$pdo->prepare('SELECT title AS label, "Tarefa" AS type FROM tasks WHERE title LIKE ?');$s3->execute(["%$q%"]);
    $res=array_merge($s1->fetchAll(),$s2->fetchAll(),$s3->fetchAll());
    echo '<h2>Busca Global: '.h($q).'</h2><div class="panel table-wrap"><table><tr><th>Tipo</th><th>Resultado</th></tr>'; foreach($res as $r) echo '<tr><td>'.h($r['type']).'</td><td>'.h($r['label']).'</td></tr>'; echo '</table></div>';
}
?></main></div></body></html>
